 P('4589',-14,9,1,'trans light blue'),P('3062b',-9,9,6,'trans light blue'),P('4589',-9,12,6,'trans light blue'),
 box({at:[8,3,3],size:[5,6,4],colour:'white',top:'tile'}),
 P('3039',8,9,3,'white',0),P('3039',8,9,5,'white',180),P('3039',10,9,3,'white',0),P('3039',10,9,5,'white',180),
 P('3062b',12,9,4,'trans light blue'),P('4589',12,12,4,'trans light blue'),
 P('87081',7,3,-13,'white'),P('60474',7,6,-13,'black'),P('87081',7,7,-13,'red'),P('14769',8,10,-12,'red')
]);
